import{_ as t,C as i,c as l,o as d,a6 as r,G as o,j as a,a as c}from"./chunks/framework.BY05barL.js";const p="/ucasal-ssoo-estudio/assets/17-cpu-es.WuQzx4wE.png",u="/ucasal-ssoo-estudio/assets/17-dma.BmbyOg21.png",b=JSON.parse('{"title":"Dispositivos de E/S e Interrupciones","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/dispositivos-es.md","filePath":"unidad1/dispositivos-es.md"}'),m={name:"unidad1/dispositivos-es.md"};function h(f,e,_,v,P,D){const n=i("IoInterruptDemo"),s=i("DmaDemo");return d(),l("div",null,[e[0]||(e[0]=r('<h1 id="dispositivos-de-e-s-e-interrupciones" tabindex="-1">Dispositivos de E/S e Interrupciones <a class="header-anchor" href="#dispositivos-de-e-s-e-interrupciones" aria-label="Permalink to &quot;Dispositivos de E/S e Interrupciones&quot;">​</a></h1><h2 id="iniciar-un-dispositivo-de-e-s-y-obtener-una-interrupcion" tabindex="-1">Iniciar un dispositivo de E/S y obtener una interrupción <a class="header-anchor" href="#iniciar-un-dispositivo-de-e-s-y-obtener-una-interrupcion" aria-label="Permalink to &quot;Iniciar un dispositivo de E/S y obtener una interrupción&quot;">​</a></h2><p>El proceso para iniciar un dispositivo de entrada/salida y manejar las interrupciones que genera sigue estos pasos:</p><ol><li>El driver le indica al controlador lo que debe hacer</li><li>El controlador le indica al dispositivo lo que debe hacer</li><li>Si el controlador de interrupciones está preparado, el dispositivo le indica al CPU que terminó</li><li>El controlador de interrupciones indica el número de Bus</li></ol><p><img src="'+p+'" alt="CPU y dispositivos de E/S"></p>',5)),o(n),e[1]||(e[1]=a("h2",{id:"dma-direct-memory-access",tabindex:"-1"},[c("DMA (Direct Memory Access) "),a("a",{class:"header-anchor",href:"#dma-direct-memory-access","aria-label":'Permalink to "DMA (Direct Memory Access)"'},"​")],-1)),e[2]||(e[2]=a("p",null,"El DMA (Acceso Directo a Memoria) es una técnica que permite a los dispositivos de E/S transferir datos directamente a la memoria principal sin intervención de la CPU.",-1)),e[3]||(e[3]=a("p",null,[a("img",{src:u,alt:"DMA"})],-1)),o(s),e[4]||(e[4]=r('<h3 id="funcionamiento-del-dma" tabindex="-1">Funcionamiento del DMA <a class="header-anchor" href="#funcionamiento-del-dma" aria-label="Permalink to &quot;Funcionamiento del DMA&quot;">​</a></h3><ol><li>La CPU le indica al controlador de DMA lo que debe hacer</li><li>El controlador de DMA gestiona la transferencia de datos entre el dispositivo y la memoria</li><li>Cuando el DMA termina, genera una interrupción para notificar a la CPU</li></ol><h3 id="ventajas-del-dma" tabindex="-1">Ventajas del DMA <a class="header-anchor" href="#ventajas-del-dma" aria-label="Permalink to &quot;Ventajas del DMA&quot;">​</a></h3><ul><li>Reduce la carga de trabajo de la CPU</li><li>Aumenta el rendimiento del sistema</li><li>Permite transferencias de datos a alta velocidad</li><li>Libera a la CPU para realizar otras tareas mientras se transfieren los datos</li></ul><h2 id="tipos-de-transferencia-de-e-s" tabindex="-1">Tipos de Transferencia de E/S <a class="header-anchor" href="#tipos-de-transferencia-de-e-s" aria-label="Permalink to &quot;Tipos de Transferencia de E/S&quot;">​</a></h2><h3 id="e-s-programada" tabindex="-1">E/S Programada <a class="header-anchor" href="#e-s-programada" aria-label="Permalink to &quot;E/S Programada&quot;">​</a></h3><ul><li>La CPU ejecuta instrucciones que controlan directamente el dispositivo de E/S</li><li>La CPU verifica constantemente el estado del dispositivo (polling)</li><li>Ineficiente para dispositivos lentos</li></ul><h3 id="e-s-por-interrupciones" tabindex="-1">E/S por Interrupciones <a class="header-anchor" href="#e-s-por-interrupciones" aria-label="Permalink to &quot;E/S por Interrupciones&quot;">​</a></h3><ul><li>La CPU inicia la operación de E/S y continúa con otras tareas</li><li>Cuando el dispositivo termina, genera una interrupción</li><li>La CPU atiende la interrupción y procesa los datos</li><li>Más eficiente que la E/S programada</li></ul><h3 id="e-s-por-dma" tabindex="-1">E/S por DMA <a class="header-anchor" href="#e-s-por-dma" aria-label="Permalink to &quot;E/S por DMA&quot;">​</a></h3><ul><li>La CPU configura el controlador de DMA</li><li>El DMA gestiona la transferencia de datos</li><li>La CPU recibe una interrupción cuando la transferencia termina</li><li>Muy eficiente para transferencias de grandes cantidades de datos</li></ul>',11))])}const S=t(m,[["render",h]]);export{b as __pageData,S as default};
